// --- State---────────────────────────────────────────────────────────────────────
let currentTaskIdx = 0;
let currentStepIdx = 0;
let completedTasks = [];
let settings = { tts: false, text: false, large: false, contrast: false, calm: 0, timeMode: 'digital', weekdays: true };
let pinBuffer = '';
let pinTarget = null;
let pauseTimer = null;
let pauseSeconds = 10; // Demo: 10 Sekunden
let pauseRemaining = pauseSeconds;

// --- Initialisierung---──────────────────────────────────────────────────────────
function init() {
  buildWeekBar();
  buildTaskList();
  updateClock();
  setInterval(updateClock, 1000);
}

// --- Wochenbalken---─────────────────────────────────────────────────────────────
function buildWeekBar() {
  const days = ['So','Mo','Di','Mi','Do','Fr','Sa'];
  const today = new Date().getDay(); // 0=So
  const bar = document.getElementById('weekBar');
  bar.innerHTML = '';
  days.forEach((d, i) => {
    const el = document.createElement('div');
    el.className = 'week-day' + (i === today ? ' today' : '');
    el.innerHTML = `<div class="week-day-label">${d}</div>`;
    bar.appendChild(el);
  });
}

// --- Aufgabenliste---────────────────────────────────────────────────────────────
function buildTaskList() {
  const list = document.getElementById('taskList');
  list.innerHTML = '';
  const flowLine = document.getElementById('flowLine');
  // Alte Flow-Dots entfernen (v-line bleibt)
  flowLine.querySelectorAll('.flow-dot').forEach(d => d.remove());

  const cardHeight = 92; // px pro Karte (inkl. gap)
  const cardGap = 10;
  let doneCount = 0;

  TASKS.forEach((t, i) => {
    const isDone   = completedTasks.includes(i);
    const isActive = i === currentTaskIdx && !isDone;
    const isFuture = i > currentTaskIdx && !isDone;
    if (isDone) doneCount++;

    let cls = 'task-card';
    if (isActive) cls += ' active';
    if (isDone)   cls += ' done';
    if (isFuture) cls += ' future';

    const timeHtml = buildTimeBlock(t.time);
    const statusHtml = isDone
      ? `<div class="task-status done-icon"><img src="${SVG_DONE}" alt="Erledigt"/></div>`
      : isActive
        ? `<div class="task-status play" onclick="startTask(${i})"><svg viewBox="0 0 24 24" fill="white" width="22" height="22"><polygon points="6,3 20,12 6,21"/></svg></div>`
        : `<div class="task-status" style="background:#E5E7EB;border:2px solid #9CA3AF"></div>`;

    const arrowHtml = isActive
      ? `<img class="task-arrow" src="${SVG_PFEIL}" alt="Aktuell"/>`
      : '';

    // Ort-Bild: jede Aufgabe hat ein locThumb
    const locThumb = t.locThumb ? `<img class="task-thumb" src="${t.locThumb}" alt="Ort" style="width:48px;height:48px;border-radius:var(--r-sm);object-fit:cover;flex-shrink:0"/>` : '';

    const card = document.createElement('div');
    card.className = cls;
    if (isActive || (!isFuture && !isDone)) card.onclick = () => startTask(i);
    card.innerHTML = `
      ${timeHtml}
      <img class="task-thumb" src="${t.thumb}" alt="${t.name}"/>
      ${locThumb}
      <div class="task-info">
        <div class="task-name">${t.name}</div>
      </div>
      ${statusHtml}
      ${arrowHtml}
    `;
    list.appendChild(card);

    // Flow-Dot für diese Aufgabe
    const dot = document.createElement('div');
    const topOffset = 20 + i * (cardHeight + cardGap) + (isActive ? 2 : 0);
    dot.className = 'flow-dot' + (isDone ? ' done' : isActive ? ' current' : '');
    dot.style.top = topOffset + 'px';
    flowLine.appendChild(dot);
  });

  // Grüne Linie: reicht bis zum Mittelpunkt des letzten erledigten Dots (pixelgenau)
  const doneLine = document.getElementById('vLineDone');
  if (doneLine) {
    if (doneCount === 0) {
      doneLine.style.height = '0px';
    } else {
      // Index der letzten erledigten Aufgabe
      let lastDoneIdx = -1;
      for (let i = TASKS.length - 1; i >= 0; i--) {
        if (completedTasks.includes(i)) { lastDoneIdx = i; break; }
      }
      // Dot-Unterkante = topOffset + 18px (volle Dot-Hoehe 18px) damit Linie komplett durch Dot laeuft
      const dotBottom = 20 + lastDoneIdx * (cardHeight + cardGap) + 18;
      doneLine.style.height = dotBottom + 'px';
    }
  }
}

function buildTimeBlock(timeStr) {
  const mode = settings.timeMode;
  if (mode === 'analog') {
    const [h, m] = timeStr.split(':').map(Number);
    const svgClock = buildAnalogClockSVG(h, m, 56, true); // staticClock=true: kein Sekundenzeiger
    return `<div class="time-block analog-mode">${svgClock}</div>`;
  } else if (mode === 'symbol') {
    const [h] = timeStr.split(':').map(Number);
    const svgSym = h < 12
      ? `<svg viewBox="0 0 36 36" width="36" height="36"><path d="M18 10 A8 8 0 0 1 26 18 A8 8 0 0 1 18 26" fill="#F9A825"/><line x1="18" y1="2" x2="18" y2="6" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="28" y1="6" x2="25" y2="9" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="34" y1="18" x2="30" y2="18" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="8" y1="6" x2="11" y2="9" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="2" y1="18" x2="6" y2="18" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="18" y1="30" x2="18" y2="34" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/></svg>`
      : h < 17
      ? `<svg viewBox="0 0 36 36" width="36" height="36"><circle cx="18" cy="18" r="8" fill="#F9A825"/><line x1="18" y1="2" x2="18" y2="6" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="28" y1="6" x2="25" y2="9" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="34" y1="18" x2="30" y2="18" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="8" y1="6" x2="11" y2="9" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="2" y1="18" x2="6" y2="18" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="18" y1="30" x2="18" y2="34" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="28" y1="30" x2="25" y2="27" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="8" y1="30" x2="11" y2="27" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/></svg>`
      : `<svg viewBox="0 0 36 36" width="36" height="36"><path d="M22 8 A10 10 0 1 0 22 28 A7 7 0 1 1 22 8Z" fill="#5B4B8A"/></svg>`;
    return `<div class="time-block" style="background:#EEF4FF;padding:8px;display:flex;align-items:center;justify-content:center">${svgSym}</div>`;
  } else {
    return `<div class="time-block">${timeStr}</div>`;
  }
}

// --- Analoge Uhr als SVG---──────────────────────────────────────────────────────
function buildAnalogClockSVG(h, m, size=56, staticClock=false) {
  const cx = size/2, cy = size/2, r = size/2 - 3;
  // Zeiger-Winkel
  const mAngle = (m / 60) * 360 - 90;
  const hAngle = ((h % 12) / 12 + m / 720) * 360 - 90;
  const mRad = mAngle * Math.PI / 180;
  const hRad = hAngle * Math.PI / 180;
  const mLen = r * 0.75, hLen = r * 0.5;
  const mx = cx + Math.cos(mRad) * mLen, my = cy + Math.sin(mRad) * mLen;
  const hx = cx + Math.cos(hRad) * hLen, hy = cy + Math.sin(hRad) * hLen;
  // Sekunden (orange, zeigt auf aktuelle Sekunde)
  const now = new Date();
  const sAngle = (now.getSeconds() / 60) * 360 - 90;
  const sRad = sAngle * Math.PI / 180;
  const sx = cx + Math.cos(sRad) * (r * 0.85), sy = cy + Math.sin(sRad) * (r * 0.85);
  // Zahlen
  let nums = '';
  for (let i = 1; i <= 12; i++) {
    const a = (i / 12) * 360 - 90;
    const rad = a * Math.PI / 180;
    const nr = r * 0.78;
    const nx = cx + Math.cos(rad) * nr, ny = cy + Math.sin(rad) * nr;
    nums += `<text x="${nx}" y="${ny}" text-anchor="middle" dominant-baseline="central" font-size="${size*0.14}" font-weight="bold" fill="#1A1A1A">${i}</text>`;
  }
  const secLine = staticClock ? '' : `<line x1="${cx}" y1="${cy}" x2="${sx}" y2="${sy}" stroke="#E07B00" stroke-width="${size*0.025}" stroke-linecap="round"/>`;
  return `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
    <circle cx="${cx}" cy="${cy}" r="${r}" fill="white" stroke="#1A1A1A" stroke-width="2.5"/>
    ${nums}
    <line x1="${cx}" y1="${cy}" x2="${hx}" y2="${hy}" stroke="#1A1A1A" stroke-width="${size*0.055}" stroke-linecap="round"/>
    <line x1="${cx}" y1="${cy}" x2="${mx}" y2="${my}" stroke="#1A1A1A" stroke-width="${size*0.035}" stroke-linecap="round"/>
    ${secLine}
    <circle cx="${cx}" cy="${cy}" r="${size*0.05}" fill="#1A1A1A"/>
  </svg>`;
}

// --- Uhr aktualisieren---────────────────────────────────────────────────────────
function updateClock() {
  const now = new Date();
  const h = String(now.getHours()).padStart(2,'0');
  const m = String(now.getMinutes()).padStart(2,'0');
  const timeStr = h + ':' + m;
  const mode = settings.timeMode;
  ['clockHome','clockTask','clockPause'].forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    if (mode === 'analog') {
      // Analog: größere Uhr (72px)
      el.innerHTML = buildAnalogClockSVG(now.getHours(), now.getMinutes(), 72);
      el.classList.remove('digital-box');
      el.style.fontSize = '0';
    } else if (mode === 'symbol') {
      const hr = now.getHours();
      // Symbol: größere SVGs (52px)
      const svgTopSym = hr < 12
        ? `<svg viewBox="0 0 36 36" width="52" height="52"><path d="M18 10 A8 8 0 0 1 26 18 A8 8 0 0 1 18 26" fill="#F9A825"/><line x1="18" y1="2" x2="18" y2="6" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="28" y1="6" x2="25" y2="9" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="34" y1="18" x2="30" y2="18" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="8" y1="6" x2="11" y2="9" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="2" y1="18" x2="6" y2="18" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="18" y1="30" x2="18" y2="34" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/></svg>`
        : hr < 17
        ? `<svg viewBox="0 0 36 36" width="52" height="52"><circle cx="18" cy="18" r="8" fill="#F9A825"/><line x1="18" y1="2" x2="18" y2="6" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="28" y1="6" x2="25" y2="9" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="34" y1="18" x2="30" y2="18" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="8" y1="6" x2="11" y2="9" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="2" y1="18" x2="6" y2="18" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="18" y1="30" x2="18" y2="34" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="28" y1="30" x2="25" y2="27" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/><line x1="8" y1="30" x2="11" y2="27" stroke="#F9A825" stroke-width="2.5" stroke-linecap="round"/></svg>`
        : `<svg viewBox="0 0 36 36" width="52" height="52"><path d="M22 8 A10 10 0 1 0 22 28 A7 7 0 1 1 22 8Z" fill="#5B4B8A"/></svg>`;
      el.innerHTML = svgTopSym;
      el.classList.remove('digital-box');
      el.style.fontSize = '0';
    } else {
      // Digital: Rechteck-Design mit Uhr-Icon
      el.innerHTML = `<svg viewBox="0 0 24 24" width="22" height="22" style="flex-shrink:0"><circle cx="12" cy="12" r="10" stroke="var(--time-color)" stroke-width="2" fill="none"/><line x1="12" y1="7" x2="12" y2="12" stroke="var(--time-color)" stroke-width="2" stroke-linecap="round"/><line x1="12" y1="12" x2="16" y2="14" stroke="var(--time-color)" stroke-width="2" stroke-linecap="round"/></svg><span style="font-size:26px;font-weight:900;color:var(--time-color);letter-spacing:1px">${timeStr}</span>`;
      el.classList.add('digital-box');
      el.style.fontSize = '0';
    }
  });
  // Aufgabenliste neu bauen wenn Zeitdarstellung analog (für Uhren in Karten)
  if (mode === 'analog') buildTaskList();
}

// --- Aufgabe starten---──────────────────────────────────────────────────────────
function startTask(idx) {
  const task = TASKS[idx];
  if (!task) return;
  if (task.isFeierabend) { showView('feierabend'); return; }
  currentTaskIdx = idx;
  currentStepIdx = 0;
  renderStep();
  showView('task');
}

// --- Schritt rendern---──────────────────────────────────────────────────────────
function renderStep() {
  const task = TASKS[currentTaskIdx];
  const steps = task.steps;
  const step = steps[currentStepIdx];

  // Orts-Pin: nur bei type=ort anzeigen
  const ortPin = document.getElementById('ortPin');
  if (ortPin) ortPin.style.display = step.type === 'ort' ? 'block' : 'none';

  // Schrittbalken — alle Schritte gleiche Farbe (kein Orange für Ort)
  const dots = document.getElementById('stepDots');
  dots.innerHTML = '';
  steps.forEach((s, i) => {
    const dot = document.createElement('div');
    dot.className = 'step-dot';
    if (i < currentStepIdx) {
      dot.innerHTML = `<img src="${SVG_DONE}" alt="Erledigt"/>`;
    } else if (i === currentStepIdx) {
      dot.innerHTML = `<img src="${SVG_ACTIVE}" alt="Aktiv"/>`;
    } else {
      dot.innerHTML = `<img src="${SVG_OPEN}" alt="Offen"/>`;
    }
    dots.appendChild(dot);
  });

  // Bild
  document.getElementById('taskImgEl').src = step.img;

  // Audio-Text + Audio-Button (nur wenn TTS aktiv)
  document.getElementById('audioText').textContent = step.audio;
  const btnAudio = document.getElementById('btnAudio');
  if (btnAudio) btnAudio.style.display = settings.tts ? 'flex' : 'none';

  // Button-Label
  const isLast = currentStepIdx === steps.length - 1;
  const btnLabel = document.getElementById('btnWeiterLabel');
  const btnWeiter = document.getElementById('btnWeiter');
  if (step.type === 'ort') {
    btnLabel.textContent = 'Weiter';
    btnWeiter.className = 'btn btn-weiter';
  } else if (isLast) {
    btnLabel.textContent = 'Fertig';
    btnWeiter.className = 'btn btn-fertig';
  } else {
    btnLabel.textContent = 'Weiter';
    btnWeiter.className = 'btn btn-weiter';
  }

  // Zurück-Button: beim ersten Schritt → Hauptsicht, sonst einen Schritt zurück
  const btnZurueck = document.getElementById('btnZurueck');
  btnZurueck.style.opacity = '1';
  btnZurueck.disabled = false;

  // TTS: automatisch vorlesen
  speakAuto(step.audio);
}

// --- Navigation---───────────────────────────────────────────────────────────────
function nextStep() {
  const task = TASKS[currentTaskIdx];
  const steps = task.steps;
  const step = steps[currentStepIdx];

  // Sonderfall Pause:
  // Nach dem Orts-Schritt zur Kantine soll die Pause-Sicht erscheinen,
  // nicht der Fertig-Dialog. Die Pause-Aufgabe hat nur einen Orts-Schritt.
  if (task.isPause && step && step.type === 'ort') {
    showView('pause');
    startPauseTimer();
    return;
  }

  const isLast = currentStepIdx === steps.length - 1;

  if (isLast) {
    // Fertig-Dialog zeigen
    document.getElementById('fertigDialogImg').src = steps[currentStepIdx].img;
    document.getElementById('overlayFertig').classList.add('show');
    speakAuto('Bist du fertig?');
    return;
  }

  currentStepIdx++;
  renderStep();
}

function goBack() {
  if (currentStepIdx === 0) {
    // Schritt 0 → zurück zur Hauptsicht
    showView('home');
    return;
  }
  currentStepIdx--;
  renderStep();
}

function confirmFertig() {
  document.getElementById('overlayFertig').classList.remove('show');
  completedTasks.push(currentTaskIdx);
  // Nächste aktive Aufgabe
  for (let i = currentTaskIdx + 1; i < TASKS.length; i++) {
    if (!completedTasks.includes(i)) { currentTaskIdx = i; break; }
  }
  showView('reward');
}

function rewardDone() {
  buildTaskList();
  showView('home');
}

// --- Pause-Timer---──────────────────────────────────────────────────────────────
function startPauseTimer() {
  pauseRemaining = pauseSeconds;
  if (pauseTimer) clearInterval(pauseTimer);
  pauseTimer = setInterval(() => {
    pauseRemaining = Math.max(0, pauseRemaining - 1);
    drawPauseTimer();
    if (pauseRemaining === 0) {
      clearInterval(pauseTimer);
      // Grünes Häkchen anzeigen
      const check = document.getElementById('pauseDoneCheck');
      if (check) check.style.display = 'block';
      // Fertig-Button pulsiert
      const btn = document.getElementById('btnPauseEnd');
      if (btn) btn.style.animation = 'pulse 1s ease-in-out 3';
      // TTS: nur wenn aktiviert
      speakAuto('Pause ist vorbei.');
    }
  }, 1000);
  drawPauseTimer();
}

function drawPauseTimer() {
  const canvas = document.getElementById('pauseTimerCanvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const w = 120, h = 120, cx = 60, cy = 60, r = 50;
  ctx.clearRect(0, 0, w, h);
  // Hintergrund-Ring (grau)
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.strokeStyle = '#E5E7EB'; ctx.lineWidth = 12; ctx.stroke();
  // Fortschritt-Ring (blau/türkis, keine Zahlen)
  const progress = pauseRemaining / pauseSeconds;
  const startAngle = -Math.PI / 2;
  const endAngle = startAngle + (1 - progress) * Math.PI * 2;
  ctx.beginPath(); ctx.arc(cx, cy, r, startAngle, endAngle);
  ctx.strokeStyle = '#0F766E'; // Türkis, ruhig
  ctx.lineWidth = 12; ctx.lineCap = 'round'; ctx.stroke();
  // Kein Text, keine Zahlen
}

function pauseEnd() {
  if (pauseTimer) clearInterval(pauseTimer);
  completedTasks.push(currentTaskIdx);
  for (let i = currentTaskIdx + 1; i < TASKS.length; i++) {
    if (!completedTasks.includes(i)) { currentTaskIdx = i; break; }
  }
  buildTaskList();
  showView('reward');
}

