// --- Einstellungen---────────────────────────────────────────────────────────────
function openSettings() {
  document.getElementById('settingsPanel').classList.add('show');
  // Toggles aktualisieren
  document.getElementById('togWeekdays').className = 'toggle' + (settings.weekdays ? ' on' : '');
  document.getElementById('togTTS').className      = 'toggle' + (settings.tts      ? ' on' : '');
  document.getElementById('togText').className     = 'toggle' + (settings.text     ? ' on' : '');
  document.getElementById('togLarge').className    = 'toggle' + (settings.large    ? ' on' : '');
  document.getElementById('togContrast').className = 'toggle' + (settings.contrast ? ' on' : '');
  document.getElementById('selCalm').value  = String(settings.calm);
  document.getElementById('selTime').value  = settings.timeMode;
}
function closeSettings() {
  document.getElementById('settingsPanel').classList.remove('show');
}

function toggleSetting(key) {
  settings[key] = !settings[key];
  applySettings();
  openSettings(); // Toggles neu rendern
}

function applySettings() {
  const body = document.body;
  const frame = document.getElementById('appFrame');
  body.classList.toggle('mode-contrast', settings.contrast);
  body.classList.toggle('size-large', settings.large);
  frame.classList.toggle('text-off', settings.text);
  // Calm-Modus
  body.classList.remove('mode-calm-2','mode-calm-3');
  if (settings.calm === 2) body.classList.add('mode-calm-2');
  if (settings.calm === 3) body.classList.add('mode-calm-3');
  // Wochentage ein/ausblenden
  const wb = document.getElementById('weekBar');
  if (wb) wb.style.display = settings.weekdays ? '' : 'none';
}

function applyCalm() {
  settings.calm = parseInt(document.getElementById('selCalm').value);
  applySettings();
}

function applyTimeMode() {
  settings.timeMode = document.getElementById('selTime').value;
  buildTaskList();
  updateClock();
  updatePlanchangeTime();
}

// --- PIN---──────────────────────────────────────────────────────────────────────
function profileLongPress() {
  // Einfacher Klick öffnet direkt Einstellungen (für Demo)
  pinBuffer = '';
  document.getElementById('pinDisplay').textContent = '____';
  document.getElementById('pinError').textContent = '';
  document.getElementById('pinOverlay').classList.add('show');
}

function pinKey(k) {
  if (k === 'cancel') {
    document.getElementById('pinOverlay').classList.remove('show');
    return;
  }
  if (k === 'del') {
    pinBuffer = pinBuffer.slice(0,-1);
  } else {
    if (pinBuffer.length < 4) pinBuffer += k;
  }
  const disp = pinBuffer.padEnd(4,'_').split('').map(c => c === '_' ? '_' : '●').join('');
  document.getElementById('pinDisplay').textContent = disp;
  if (pinBuffer.length === 4) {
    if (pinBuffer === '1234') {
      document.getElementById('pinOverlay').classList.remove('show');
      openSettings();
    } else {
      document.getElementById('pinError').textContent = 'Falscher PIN';
      pinBuffer = '';
      document.getElementById('pinDisplay').textContent = '____';
    }
  }
}

// --- Sprachausgabe---────────────────────────────────────────────────────────────────────────────────
function speak(text) {
  if (!('speechSynthesis' in window)) return;
  window.speechSynthesis.cancel();
  const u = new SpeechSynthesisUtterance(text);
  u.lang = 'de-DE'; u.rate = 0.88;
  window.speechSynthesis.speak(u);
}
// Automatische Sprachausgabe: nur wenn TTS aktiviert
function speakAuto(text) {
  if (!settings.tts) return;
  speak(text);
}
// Manuelle Sprachausgabe (Button-Klick): nur wenn TTS aktiviert
function speakButton(text) {
  if (!settings.tts) return;
  speak(text);
}
function speakCurrent() {
  const task = TASKS[currentTaskIdx];
  if (!task) return;
  const step = task.steps[currentStepIdx];
  if (!step) return;
  speakButton(step.audio);
}

// -- Planänderung-Zeitdarstellung aktualisieren --
function updatePlanchangeTime() {
  const oldEl = document.getElementById('planOldTime');
  const newEl = document.getElementById('planNewTime');
  if (oldEl) oldEl.innerHTML = buildTimeBlock('13:00');
  if (newEl) newEl.innerHTML = buildTimeBlock('13:00');
}

// --- View-Wechsel---─────────────────────────────────────────────────────────────
function showView(name) {
  document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
  const map = {
    home: 'viewHome', task: 'viewTask', pause: 'viewPause',
    reward: 'viewReward', feierabend: 'viewFeierabend',
    erinnerung: 'viewErinnerung', planchange: 'viewPlanchange',
  };
  const el = document.getElementById(map[name]);
  if (el) el.classList.add('active');
  if (name === 'home') buildTaskList();
  if (name === 'planchange') updatePlanchangeTime();
  // TTS für verschiedene Sichten
  if (name === 'feierabend') speakAuto('Feierabend! Gute Arbeit heute.');
  if (name === 'planchange') speakAuto('Achtung! Es gibt eine Planänderung.');
  if (name === 'erinnerung') speakAuto('Erinnerung: Hände waschen um 9 Uhr.');
  if (name === 'reward') speakAuto('Super! Du hast die Aufgabe erledigt.');
}

